.vitals{width:min(31vw,370px);min-width:220px}
.vital-head{display:flex;justify-content:space-between;align-items:flex-end;line-height:1;margin:0 1px 5px}
.callsign{font-size:12px;font-weight:700;letter-spacing:.18em;color:#d9f9ff;text-shadow:0 1px 8px #000}
.callsign b{color:var(--cyan);font-weight:600}
.vital-number{font-family:var(--display);font-size:19px;letter-spacing:.08em;color:var(--white);text-shadow:0 0 9px rgba(53,233,255,.45)}
.energy-head{margin-top:7px}
.energy-head .callsign{font-size:10px;color:#8ca5bb}
.energy-head .vital-number{font-size:15px;color:var(--electric)}
.bar{position:relative;height:15px;overflow:hidden;background:rgba(1,7,15,.86);border:1px solid rgba(131,214,255,.3);clip-path:polygon(0 0,100% 0,calc(100% - 8px) 100%,0 100%)}
.bar:before{content:"";position:absolute;inset:3px;background:repeating-linear-gradient(90deg,rgba(255,255,255,.1) 0 1px,transparent 1px 12.5%);z-index:3;opacity:.45}
.bar i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#1882ff,#34eaff 62%,#c5fbff);box-shadow:0 0 16px rgba(40,224,255,.75);transform-origin:left;transition:transform .25s cubic-bezier(.2,.75,.2,1),filter .2s}
.bar em{position:absolute;left:0;top:0;height:100%;width:100%;background:rgba(255,240,240,.55);transform-origin:left;z-index:1;transition:transform .8s .15s;opacity:.45}
.bar .bar-glint{position:absolute;inset:0;background:linear-gradient(110deg,transparent 20%,rgba(255,255,255,.32) 50%,transparent 80%);transform:translateX(-100%);animation:barShine 4s 1.5s infinite;z-index:2}
@keyframes barShine{0%,65%{transform:translateX(-120%)}85%,100%{transform:translateX(120%)}}
.bar.low i{background:linear-gradient(90deg,#ff203f,#ff6074);box-shadow:0 0 16px rgba(255,56,83,.7);animation:lowPulse .6s ease-in-out infinite alternate}
@keyframes lowPulse{to{filter:brightness(1.5)}}
.battery{display:grid;grid-template-columns:repeat(10,1fr);gap:3px;height:9px;padding:1px 0}
.battery b{position:relative;background:rgba(54,101,142,.22);border:1px solid rgba(100,174,225,.16);transform:skewX(-17deg);transition:background .18s,box-shadow .18s}
.battery b.full{background:linear-gradient(180deg,#b6fbff,#248eff);border-color:rgba(149,243,255,.7);box-shadow:0 0 8px rgba(45,193,255,.7)}
.battery b.flick{animation:batteryFlick .9s linear infinite}
@keyframes batteryFlick{50%{opacity:.45}}
.round-panel{display:flex;align-items:center;gap:17px;padding:9px 15px 10px 18px;border-top:1px solid rgba(116,220,255,.25);border-bottom:1px solid rgba(116,220,255,.14);background:linear-gradient(90deg,rgba(4,11,24,.2),rgba(4,11,24,.75));clip-path:polygon(14px 0,100% 0,100% 100%,0 100%,0 14px)}
.round-block{display:flex;align-items:baseline;gap:8px}
.round-block span{max-width:75px;font-size:9px;line-height:1.05;letter-spacing:.13em;color:#7fa4ba}
.round-block strong{font-family:var(--display);font-size:31px;font-weight:400;letter-spacing:.04em;line-height:.9;color:var(--white);text-shadow:0 0 16px rgba(51,225,255,.38)}
.round-block.kills strong{color:var(--cyan)}
.round-slash{width:1px;height:25px;background:linear-gradient(transparent,var(--line),transparent)}
.combo-readout{position:absolute;z-index:7;left:var(--safe-left);top:112px;display:flex;align-items:center;gap:9px;opacity:0;transform:translateX(-16px) skewX(-5deg);transition:opacity .18s,transform .18s;pointer-events:none;text-shadow:0 0 16px rgba(45,230,255,.55)}
.combo-readout.show{opacity:1;transform:translateX(0) skewX(-5deg)}
.combo-readout>span{font-family:var(--display);font-size:54px;line-height:.75;color:var(--cyan);-webkit-text-stroke:1px rgba(210,252,255,.7)}
.combo-readout div{display:flex;flex-direction:column;line-height:1;padding-top:4px}
.combo-readout b{font-size:12px;letter-spacing:.21em;color:#fff}
.combo-readout small{font-size:9px;letter-spacing:.13em;color:#7e9aae;margin-top:4px}
.wave-banner{position:absolute;z-index:9;left:50%;top:19%;transform:translate(-50%,-10px);display:flex;flex-direction:column;align-items:center;text-align:center;opacity:0;pointer-events:none;transition:opacity .35s,transform .35s}
.wave-banner.show{opacity:1;transform:translate(-50%,0)}
.wave-banner:before,.wave-banner:after{content:"";position:absolute;top:26px;width:140px;height:1px;background:linear-gradient(90deg,transparent,var(--cyan));box-shadow:0 0 8px var(--cyan)}
.wave-banner:before{right:112%}
.wave-banner:after{left:112%;transform:scaleX(-1)}
.wave-banner span{font-size:10px;letter-spacing:.38em;color:var(--cyan);margin-bottom:5px}
.wave-banner strong{font-family:var(--display);font-size:45px;font-weight:400;letter-spacing:.09em;line-height:1;text-shadow:0 0 25px rgba(51,223,255,.48)}
.wave-banner small{font-size:9px;letter-spacing:.23em;color:#7c9ab0;margin-top:7px}
.context-hint{position:absolute;z-index:7;left:50%;bottom:22px;transform:translateX(-50%);padding:7px 12px;border:1px solid rgba(83,210,255,.18);background:rgba(2,9,20,.62);backdrop-filter:blur(8px);color:#7797ad;font-size:10px;letter-spacing:.1em;white-space:nowrap;opacity:0;transition:opacity .3s;pointer-events:none}
.context-hint.show{opacity:1}
.context-hint kbd{display:inline-block;padding:1px 5px;margin:0 1px;border:1px solid rgba(77,215,255,.35);background:rgba(33,129,183,.16);color:#c9f8ff;font-family:var(--ui);font-size:9px}
.context-hint b{color:var(--cyan);margin-left:4px}
[data-screen="playing"] .context-hint{animation:hintFade 8s forwards}
@keyframes hintFade{0%,75%{opacity:1}100%{opacity:0}}

/* ---------- TOUCH CONTROLS ---------- */
.touch-ui{position:absolute;z-index:10;inset:auto var(--safe-right) var(--safe-bottom) var(--safe-left);display:flex;justify-content:space-between;align-items:flex-end;pointer-events:none;opacity:0;transform:translateY(18px);transition:opacity .35s,transform .35s}
[data-screen="playing"] .touch-ui{opacity:1;transform:none}
[data-screen="gameover"] .touch-ui,[data-screen="paused"] .touch-ui,[data-screen="ad"] .touch-ui{opacity:0;transform:translateY(18px)}
.touch-ui button{pointer-events:auto}
.dpad{position:relative;width:154px;height:143px;flex:0 0 auto;opacity:.9}
.pad{position:absolute;display:flex;flex-direction:column;align-items:center;justify-content:center;width:49px;height:48px;border:1px solid rgba(96,211,255,.25);background:linear-gradient(145deg,rgba(18,54,83,.55),rgba(3,11,22,.72));backdrop-filter:blur(8px);color:#bfeaff;clip-path:polygon(6px 0,100% 0,100% calc(100% - 6px),calc(100% - 6px) 100%,0 100%,0 6px);box-shadow:inset 0 0 16px rgba(35,169,255,.08),0 7px 20px rgba(0,0,0,.2);transition:background .08s,transform .08s,border-color .08s}
.pad:hover,.action:hover{border-color:rgba(126,235,255,.55)}
.pad:active,.pad.held{background:linear-gradient(145deg,rgba(43,202,255,.36),rgba(9,54,82,.84));border-color:var(--cyan);transform:scale(.94);box-shadow:0 0 22px rgba(39,211,255,.2),inset 0 0 20px rgba(52,224,255,.13)}
.pad span{font-size:16px;line-height:1;filter:drop-shadow(0 0 5px rgba(79,226,255,.65))}
.pad small{font-size:6.5px;letter-spacing:.1em;color:#6e96ab;margin-top:3px}
.pad.up{left:53px;top:0;clip-path:polygon(0 0,100% 0,100% calc(100% - 6px),calc(100% - 6px) 100%,0 100%)}
.pad.left{left:0;top:51px}
.pad.right{left:105px;top:51px}
.pad.down{left:53px;top:101px;height:42px}
.pad-center{position:absolute;left:56px;top:55px;width:40px;height:37px;display:grid;place-items:center;background:rgba(3,11,23,.62);border:1px solid rgba(80,173,222,.11);clip-path:polygon(8px 0,100% 0,100% 70%,72% 100%,0 100%,0 24%)}
.pad-center i{width:8px;height:8px;border:1px solid rgba(76,219,255,.55);border-radius:50%;box-shadow:0 0 10px rgba(45,223,255,.55);animation:centerPulse 2s infinite}
@keyframes centerPulse{50%{box-shadow:0 0 4px rgba(45,223,255,.2);opacity:.5}}
.action-cluster{position:relative;width:222px;height:168px;flex:0 0 auto;opacity:.92}
.action{position:absolute;display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px solid rgba(100,218,255,.3);background:radial-gradient(circle at 35% 25%,rgba(36,68,98,.62),rgba(4,12,25,.8));backdrop-filter:blur(8px);clip-path:polygon(12px 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%,0 12px);box-shadow:inset 0 0 20px rgba(50,173,255,.07),0 10px 25px rgba(0,0,0,.25);transition:transform .08s,background .1s,border-color .1s}
.action .action-glyph{font-family:var(--ui);font-size:22px;line-height:1;margin-bottom:2px;color:var(--cyan);filter:drop-shadow(0 0 5px rgba(51,224,255,.65))}
.action b{font-size:9px;letter-spacing:.1em;font-weight:700;line-height:1}
.action kbd{position:absolute;right:5px;top:4px;font-family:var(--ui);font-size:7px;color:#5e7d93;border:1px solid rgba(119,163,187,.25);padding:0 2px;line-height:1.25;border-radius:2px}
.action small{font-size:7px;line-height:1;margin-top:2px;color:#7a91a5}
.action:active,.action.held{transform:scale(.92);border-color:var(--cyan);background:radial-gradient(circle at 35% 25%,rgba(46,193,255,.32),rgba(9,41,66,.9));box-shadow:0 0 26px rgba(39,209,255,.24),inset 0 0 18px rgba(66,227,255,.12)}
.action-quick{width:61px;height:58px;left:22px;bottom:35px;border-color:rgba(86,231,255,.5)}
.action-quick .action-glyph{font-size:28px;color:#76f1ff}
.action-heavy{width:60px;height:57px;left:78px;top:17px;border-color:rgba(255,99,167,.34)}
.action-heavy .action-glyph{color:#ff75bc;filter:drop-shadow(0 0 6px rgba(255,59,158,.5))}
.action-grab{width:57px;height:52px;left:0;top:36px;border-color:rgba(151,177,255,.25)}
.action-grab .action-glyph{color:#aebeff}
.action-special{width:76px;height:76px;right:0;top:43px;border-radius:0;border-color:rgba(100,226,255,.58);background:radial-gradient(circle at 40% 30%,rgba(25,93,139,.8),rgba(3,27,49,.87));box-shadow:0 0 24px rgba(33,205,255,.18),inset 0 0 28px rgba(46,211,255,.12)}
.action-special .action-glyph{font-size:31px;color:#a8fbff;text-shadow:0 0 10px #3de2ff}
.action-special b{font-size:8px;color:#cdfbff}
.special-ring{position:absolute;inset:5px;border:1px solid rgba(95,232,255,.15);border-radius:50%;animation:specialRing 3.5s linear infinite}
@keyframes specialRing{to{transform:rotate(360deg)}}
.action-special.ready{animation:specialReady 1.4s ease-in-out infinite alternate}
@keyframes specialReady{to{box-shadow:0 0 34px rgba(50,225,255,.5),inset 0 0 34px rgba(50,225,255,.24);border-color:#a8f8ff}}
.action-jump{width:52px;height:48px;left:127px;bottom:0;border-color:rgba(107,237,255,.24)}
.action-jump .action-glyph{font-size:23px}
.action[disabled]{opacity:.4}
.utility{position:absolute;z-index:12;right:var(--safe-right);top:calc(var(--safe-top) + 82px);width:31px;height:31px;display:grid;place-items:center;border:1px solid rgba(107,199,235,.14);background:rgba(3,11,22,.44);color:#6f95aa;backdrop-filter:blur(5px);transition:color .2s,border-color .2s;opacity:0;pointer-events:none}
[data-screen="playing"] .utility{opacity:1;pointer-events:auto}
.utility:hover{color:var(--cyan);border-color:rgba(83,218,255,.45)}
.utility svg{width:18px;height:18px;fill:currentColor}
.utility.pause{right:calc(var(--safe-right) + 38px);display:flex;gap:3px}
.utility.pause span{width:2px;height:11px;background:currentColor;box-shadow:0 0 6px currentColor}
.mute.muted{color:#405363}
.mute.muted:after{content:"";position:absolute;width:23px;height:1px;background:#ff526d;transform:rotate(-45deg);box-shadow:0 0 5px #ff526d}

/* ---------- OVERLAYS ---------- */
.overlay{position:absolute;inset:0;z-index:20;display:flex;flex-direction:column;transition:opacity .3s}
.eyebrow{display:flex;align-items:center;gap:8px;font-size:10px;letter-spacing:.25em;color:#7f9eb2;font-weight:700}
.eyebrow i{display:inline-block;width:17px;height:1px;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}
.btn{position:relative;display:flex;align-items:center;justify-content:space-between;gap:25px;min-height:51px;padding:0 18px 0 22px;border:1px solid rgba(92,226,255,.4);clip-path:polygon(12px 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%,0 12px);font-size:13px;font-weight:700;letter-spacing:.13em;background:rgba(6,19,35,.74);transition:transform .16s,background .16s,border-color .16s,box-shadow .16s;backdrop-filter:blur(9px)}
.btn i{font-style:normal;font-family:var(--display);font-size:24px;line-height:1;font-weight:400;color:var(--cyan);transition:transform .2s}
.btn:hover{transform:translateY(-2px);border-color:var(--cyan);box-shadow:0 8px 30px rgba(24,196,255,.14)}
.btn:hover i{transform:translateX(4px)}
.btn:active{transform:translateY(0) scale(.985)}
.btn.primary{background:linear-gradient(100deg,rgba(31,142,221,.95),rgba(15,83,167,.94) 58%,rgba(26,166,225,.9));border-color:rgba(179,249,255,.7);box-shadow:0 5px 30px rgba(24,154,255,.26),inset 0 1px rgba(255,255,255,.26);color:#f5feff;text-shadow:0 1px 8px rgba(0,26,54,.35)}
.btn.primary i{color:#fff}
.btn.ghost{background:rgba(3,11,22,.5);color:#a6c4d6;border-color:rgba(114,175,205,.21)}
.btn.tiny{min-height:34px;padding:0 12px;gap:10px;font-size:9px;clip-path:none}
.btn.tiny i{font-size:15px}
.icon-close{position:absolute;right:18px;top:14px;width:36px;height:36px;border:1px solid var(--line);font-size:23px;line-height:1;color:#8ca8b9;display:grid;place-items:center;z-index:2}
.icon-close:hover{color:var(--cyan);border-color:var(--cyan)}

/* Menu */
.menu-screen{align-items:stretch;justify-content:space-between;padding:var(--safe-top) max(30px,6vw) var(--safe-bottom);background:
  linear-gradient(90deg,rgba(2,6,13,.96) 0%,rgba(2,7,15,.88) 31%,rgba(2,7,15,.35) 59%,rgba(2,6,13,.35) 73%,rgba(2,6,13,.82) 100%),
  radial-gradient(ellipse at 72% 50%,rgba(16,89,134,.16),transparent 48%);
  overflow:hidden
}
.menu-screen:before{content:"";position:absolute;left:0;right:0;top:69%;height:1px;background:linear-gradient(90deg,transparent,rgba(62,214,255,.26),transparent);box-shadow:0 0 20px rgba(62,214,255,.2)}
.menu-screen:after{content:"07";position:absolute;right:1.5vw;bottom:-16vh;font-family:var(--display);font-size:58vh;line-height:1;color:transparent;-webkit-text-stroke:1px rgba(68,143,177,.09);pointer-events:none}
.menu-topline{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:center}
.live-tag{display:flex;align-items:center;gap:7px;font-size:8px;letter-spacing:.2em;color:#7b94a7}
.live-tag:before{content:"";width:5px;height:5px;border-radius:50%;background:var(--red);box-shadow:0 0 8px var(--red);animation:blink 1.8s infinite}
@keyframes blink{50%{opacity:.15}}
.menu-content{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:center;gap:4vw;flex:1;padding:2vh 0 1vh}
.title-lockup{max-width:min(58vw,710px);padding-left:min(2vw,30px)}
.title-kicker{margin:0 0 2px 5px;font-size:10px;letter-spacing:.31em;color:#66dff3;font-weight:700}
.title-kicker span{color:var(--pink);margin:0 5px}
.game-title{position:relative;margin:0;display:flex;flex-direction:column;font-family:var(--display);font-weight:400;font-size:clamp(100px,13.3vw,202px);line-height:.72;letter-spacing:.005em;filter:drop-shadow(0 18px 50px rgba(0,45,95,.52))}
.game-title span{display:block;position:relative;width:max-content}
.game-title span:first-child{color:transparent;-webkit-text-stroke:1.5px rgba(120,233,255,.8);text-shadow:0 0 34px rgba(49,217,255,.18);margin-left:.06em}
.game-title span:last-child{background:linear-gradient(180deg,#ecfeff 3%,#a2f4ff 37%,#2dcdf4 73%,#1675d2 100%);-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:0 0 44px rgba(31,188,255,.18)}
.game-title span:last-child:after{content:"STICK";position:absolute;left:2px;top:2px;z-index:-1;color:transparent;-webkit-text-stroke:1px rgba(255,55,152,.3);filter:blur(.2px)}
.game-title:before{content:"NEON STICK";position:absolute;left:5px;top:3px;font:inherit;font-size:1em;line-height:.72;letter-spacing:inherit;color:transparent;-webkit-text-stroke:1px rgba(52,216,255,.13);opacity:.7;display:none}
.title-rule{display:flex;align-items:center;gap:10px;margin:18px 4px 14px;max-width:455px;color:#85a4b6;font-size:9px;letter-spacing:.24em;white-space:nowrap}
.title-rule i{height:1px;background:linear-gradient(90deg,transparent,rgba(73,214,255,.5));flex:1}
.title-rule i:last-child{transform:scaleX(-1)}
.title-rule b{font-weight:600;color:#aec9d7}
.title-copy{margin:0 0 22px 4px;max-width:440px;font-size:13.5px;line-height:1.45;letter-spacing:.02em;color:#819aaa;font-weight:500}
.menu-actions{display:flex;gap:9px;max-width:465px;margin-left:3px}
.menu-actions .btn.primary{flex:1.28}
.menu-actions .btn.ghost{flex:.72;justify-content:center;gap:0}
.menu-meta{display:flex;gap:23px;margin:19px 4px 0;color:#466175;font-size:8px;letter-spacing:.15em}
.menu-meta span{display:flex;align-items:center;gap:6px}
.menu-meta b{font-family:var(--display);font-size:18px;font-weight:400;color:#9dcbd7;letter-spacing:.04em;line-height:1}
.move-card{position:relative;width:min(29vw,345px);border:1px solid rgba(108,204,239,.2);background:linear-gradient(155deg,rgba(8,21,38,.8),rgba(3,9,18,.66));backdrop-filter:blur(10px);clip-path:polygon(0 0,100% 0,100% calc(100% - 22px),calc(100% - 22px) 100%,0 100%);padding:17px 16px 0;box-shadow:0 25px 70px rgba(0,0,0,.25);margin-top:3vh}
.move-card:before{content:"";position:absolute;left:-1px;top:0;width:31%;height:2px;background:linear-gradient(90deg,var(--cyan),transparent);box-shadow:0 0 10px rgba(50,220,255,.5)}
.move-card-head{display:flex;justify-content:space-between;align-items:center;padding-bottom:11px;border-bottom:1px solid rgba(127,197,225,.12);font-size:8px;letter-spacing:.18em;color:#8db1c3}
.move-card-head b{font-family:var(--display);font-size:13px;font-weight:400;letter-spacing:.05em;color:#53768a}
.move-row{position:relative;display:grid;grid-template-columns:62px 1fr 18px;align-items:center;gap:9px;padding:11px 0;border-bottom:1px solid rgba(127,197,225,.09)}
.move-key{display:flex;align-items:center;justify-content:center;height:24px;padding:0 4px;border:1px solid rgba(97,197,231,.22);background:rgba(8,27,44,.55);color:#9bc8db;font-size:8px;letter-spacing:.02em;white-space:nowrap}
.move-row div{display:flex;flex-direction:column;min-width:0}
.move-row div b{font-size:10px;letter-spacing:.12em;color:#cdedf5;font-weight:700;line-height:1.1}
.move-row div small{font-size:8px;letter-spacing:.02em;color:#5d7b8e;font-weight:500;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.move-row>i{font-style:normal;font-family:var(--display);font-size:16px;color:#335265}
.move-row.accent .move-key{border-color:rgba(255,78,157,.34);color:#ff83b9}
.move-row.accent div b{color:#ffc2dc}
.move-footer{display:flex;justify-content:space-between;align-items:center;height:40px;padding:0 2px;font-size:7px;letter-spacing:.12em;color:#496679}
.move-footer b{font-size:8px;color:#86a8ba}
.move-footer .signal{letter-spacing:-1px;color:var(--cyan);font-size:8px}
.menu-bottom{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:center;padding-top:10px;border-top:1px solid rgba(95,160,190,.1);font-size:8px;letter-spacing:.16em;color:#40586b}
.menu-bottom span:nth-child(2){color:#5c7b90}

/* How */
.how-screen,.pause-screen,.gameover-screen,.ad-screen,{background:rgba(2,6,13,.7);backdrop-filter:blur(13px);align-items:center;justify-content:center;padding:24px}
.how-screen{background:radial-gradient(circle at 50% 40%,rgba(13,53,82,.45),rgba(2,6,13,.9) 65%);backdrop-filter:blur(15px)}
.how-card,.pause-card{position:relative;width:min(760px,92vw);border:1px solid rgba(99,209,245,.22);background:linear-gradient(150deg,rgba(8,24,42,.96),rgba(3,9,18,.97));padding:35px 38px;clip-path:polygon(0 0,calc(100% - 23px) 0,100% 23px,100% 100%,23px 100%,0 calc(100% - 23px));box-shadow:0 30px 100px rgba(0,0,0,.45)}
.how-card:before,.pause-card:before{content:"";position:absolute;left:0;top:0;width:34%;height:2px;background:linear-gradient(90deg,var(--cyan),transparent);box-shadow:0 0 12px var(--cyan)}
.how-card h2,.pause-card h2{margin:17px 0 25px;font-family:var(--display);font-size:64px;font-weight:400;line-height:.9;letter-spacing:.02em}
.how-card h2 em{font-style:normal;color:var(--cyan);text-shadow:0 0 25px rgba(47,219,255,.3)}
