    };
  }

  function spawnEnemy(kind, x, entrance = 'flank') {
    const e = makeEnemy(kind, clamp(x, view.left + 34, view.right - 34), entrance);
    state.enemies.push(e);
    addPortal(e.x, view.groundY, e.palette.core, kind === 'red' ? 1 : 1.35);
