function drawParticles() {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const p of state.particles) {
    const a = clamp(p.life / (p.maxLife || .3), 0, 1);
    if (p.type === 'spark') {
      ctx.strokeStyle = p.color;
      ctx.globalAlpha = a * .18;
      ctx.lineWidth = p.size * 2.4;
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
      ctx.lineTo(p.x - p.vx * .023, p.y - p.vy * .023);
      ctx.stroke();
      ctx.globalAlpha = a;
      ctx.lineWidth = p.size * .72;
      ctx.stroke();
    } else if (p.type === 'dust') {
      ctx.fillStyle = p.color;
      ctx.globalAlpha = a * .24;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (1.2 - a * .2), 0, TAU);
      ctx.fill();
    } else if (p.type === 'ring') {
      ctx.strokeStyle = p.color;
      ctx.globalAlpha = a * .18;
      ctx.lineWidth = p.line * 3.4 + 1;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, TAU);
      ctx.stroke();
      ctx.globalAlpha = a;
      ctx.lineWidth = p.line * a + .3;
      ctx.stroke();
    } else if (p.type === 'slash') {
      ctx.strokeStyle = p.color;
      ctx.globalAlpha = a * .18;
      ctx.lineWidth = 9 * a + 1;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * .6, p.angle - .5, p.angle + .8);
      ctx.stroke();
      ctx.globalAlpha = a;
      ctx.lineWidth = 3 * a + .3;
      ctx.stroke();
    } else if (p.type === 'arc') {
      const segments = 7;
      const dx = p.tx - p.x, dy = p.ty - p.y;
      const nx = -dy, ny = dx;
      const len = Math.hypot(nx, ny) || 1;
      const points = [];
      for (let i = 0; i <= segments; i++) {
        const t = i / segments;
        const jitter = i === 0 || i === segments ? 0 : (Math.random() - .5) * 13;
        points.push([p.x + dx * t + nx / len * jitter, p.y + dy * t + ny / len * jitter]);
      }
      ctx.strokeStyle = p.color;
      ctx.globalAlpha = a * .2;
      ctx.lineWidth = p.line * 4 + .5;
      ctx.beginPath();
      ctx.moveTo(points[0][0], points[0][1]);
      for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
      ctx.stroke();
      ctx.globalAlpha = a;
      ctx.lineWidth = p.line * a + .2;
      ctx.stroke();
    }
  }
  ctx.restore();
}

