      ctx.globalAlpha = a * .18;
      ctx.lineWidth = 9 * a + 1;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * .6, p.angle - .5, p.angle + .8);
      ctx.stroke();
      ctx.globalAlpha = a;
      ctx.lineWidth = 3 * a + .3;
      ctx.stroke();
    } else if (p.type === 'arc') {
      const segments = 7;
      const dx = p.tx - p.x, dy = p.ty - p.y;
      const nx = -dy, ny = dx;
      const len = Math.hypot(nx, ny) || 1;
      const points = [];
      for (let i = 0; i <= segments; i++) {
