    if (airborne) {
      if (Math.abs(dx) < 126 * view.actorScale && Math.abs(dy) < 120 && Math.abs(dx) < bestDist) {
        best = e; bestDist = Math.abs(dx);
      }
    } else if (Math.abs(dx) < 108 * view.actorScale && Math.abs(dy) < 92 && Math.abs(dx) < bestDist) {
