cat > /tmp/flow.mjs <<'EOF'
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args:['--no-sandbox'] });
const page = await browser.newPage({ viewport:{width:1440,height:900} });
const errors=[]; page.on('pageerror', e=>errors.push('PAGEERROR '+e.message)); page.on('console', m=>{ if(m.type()==='error') errors.push('CONSOLE '+m.text()); });
await page.goto('http://localhost:3000',{waitUntil:'networkidle'});
const snap = async () => page.evaluate(()=>{const g=NeonStick;const vis=id=>!document.querySelector(id).hidden;return {
  screen:document.querySelector('#app').dataset.screen, deaths:g.state.deaths, hp:g.player.hp, dead:g.player.dead, paused:g.state.paused,
  gameover:vis('#gameover'), ad:vis('#adPanel'), offer:vis('#reviveOffer'), actions:getComputedStyle(document.querySelector('.go-actions')).display,
  title:document.querySelector('#goTitle').innerText.replace(/\n/g,' / '), body:document.body.innerText.includes('SEGUNDA'),
  skipDisabled:document.querySelector('#skipAdBtn').disabled, adTime:g.state.adTime, pips:document.querySelector('#deathPips').textContent,
  foot:document.querySelector('.go-foot span').textContent
};});
await page.getByRole('button',{name:'Start'}).click();
await page.waitForTimeout(300);
await page.evaluate(()=>NeonStick.diePlayer());
await page.waitForTimeout(1450);
console.log('DEATH 1', await snap());
await page.screenshot({path:'screenshots/final-gameover1.png'});
await page.click('#restartBtn');
await page.waitForTimeout(500);
console.log('AFTER RESTART', await snap());
await page.evaluate(()=>NeonStick.diePlayer());
await page.waitForTimeout(1450);
console.log('DEATH 2', await snap());
await page.screenshot({path:'screenshots/final-gameover2.png'});
await page.click('#declineAdBtn');
await page.waitForTimeout(150);
console.log('DECLINED', await snap());
await page.click('#restartBtn');
await page.waitForTimeout(400);
await page.evaluate(()=>NeonStick.diePlayer());
await page.waitForTimeout(1450);
console.log('DEATH AFTER DECLINE (should be 1)', await snap());
await page.click('#restartBtn');
await page.waitForTimeout(400);
await page.evaluate(()=>NeonStick.diePlayer());
await page.waitForTimeout(1450);
console.log('SECOND AGAIN', await snap());
await page.click('#watchAdBtn');
await page.waitForTimeout(2100);
console.log('AD 2.1s', await snap());
await page.screenshot({path:'screenshots/final-ad.png'});
await page.click('#skipAdBtn');
await page.waitForTimeout(250);
console.log('REVIVED SKIP', await snap());
await page.screenshot({path:'screenshots/final-revived.png'});
console.log('ERRORS', errors);
await browser.close();
EOF
