content.text:
@font-face{font-family:'Bebas';src:url('assets/BebasNeue.ttf') format('truetype');font-weight:400;font-display:swap}
@font-face{font-family:'Rajdhani';src:url('assets/Rajdhani-Medium.ttf') format('truetype');font-weight:500;font-display:swap}
@font-face{font-family:'Rajdhani';src:url('assets/Rajdhani-SemiBold.ttf') format('truetype');font-weight:600;font-display:swap}
@font-face{font-family:'Rajdhani';src:url('assets/Rajdhani-Bold.ttf') format('truetype');font-weight:700;font-display:swap}

:root{
  --ink:#040710;
  --ink-2:#081020;
  --cyan:#35e9ff;
  --cyan-soft:#8ff5ff;
  --blue:#1c7dff;
  --electric:#51a7ff;
  --pink:#ff3b9e;
  --red:#ff4058;
  --gold:#e9ff54;
  --green:#42ff9a;
  --white:#edfaff;
  --muted:#7d93a8;
  --line:rgba(159,224,255,.2);
  --safe-top:max(16px,env(safe-area-inset-top));
  --safe-bottom:max(14px,env(safe-area-inset-bottom));
  --safe-left:max(14px,env(safe-area-inset-left));
  --safe-right:max(14px,env(safe-area-inset-right));
  --display:'Bebas','Arial Narrow',sans-serif;
  --ui:'Rajdhani','Arial Narrow',sans-serif;
}

*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
[hidden]{display:none!important}
html,body{width:100%;height:100%;margin:0;overflow:hidden;background:var(--ink);color:var(--white);font-family:var(--ui);font-weight:600;user-select:none;-webkit-user-select:none;overscroll-behavior:none}
body{touch-action:none}
button{font:inherit;color:inherit;border:0;background:none;cursor:pointer;touch-action:manipulation}
button:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}
#app{position:relative;width:100%;height:100%;height:100dvh;overflow:hidden;background:
  radial-gradient(ellipse at 50% 30%,rgba(22,55,94,.22),transparent 60%),
  linear-gradient(180deg,#03060d,#050913 60%,#020409)}
#stage{position:absolute;inset:0;display:block;width:100%;height:100%;z-index:1}

.atmosphere{position:absolute;inset:0;z-index:4;pointer-events:none}
.scanlines{position:absolute;inset:0;opacity:.09;background:repeating-linear-gradient(180deg,transparent 0 3px,rgba(0,0,0,.34) 3px 4px)}
.grain{position:absolute;inset:0;opacity:.04;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");background-size:180px 180px}
@keyframes grain{0%{transform:translate(0,0)}25%{transform:translate(2%,-1%)}50%{transform:translate(-1%,2%)}75%{transform:translate(1%,1%)}100%{transform:translate(-2%,-1%)}}
.edge-vignette{position:absolute;inset:0;background:radial-gradient(ellipse at center,transparent 47%,rgba(1,3,8,.1) 63%,rgba(1,3,8,.72) 100%),linear-gradient(180deg,rgba(2,5,12,.48),transparent 16%,transparent 78%,rgba(2,4,8,.5));}
.screen-flash{position:absolute;inset:0;opacity:0;background:radial-gradient(circle at 50% 52%,rgba(182,248,255,.8),rgba(35,145,255,.35) 34%,transparent 72%);mix-blend-mode:screen;transition:opacity .08s linear}
.screen-flash.on{opacity:.62}
.screen-flash.red{background:radial-gradient(circle at 50% 52%,rgba(255,94,109,.7),rgba(255,22,66,.25) 35%,transparent 75%)}
.speed-lines{position:absolute;inset:0;opacity:0;background:repeating-conic-gradient(from 0deg at 50% 52%,rgba(142,241,255,.15) 0deg 1deg,transparent 1deg 7deg);mask:radial-gradient(ellipse at center,transparent 0 18%,#000 52%,transparent 83%);transition:opacity .2s}
.speed-lines.on{opacity:.32}

/* ---------- HUD ---------- */
.hud{position:absolute;z-index:8;top:var(--safe-top);left:var(--safe-left);right:var(--safe-right);display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none;opacity:1;transition:opacity .35s,transform .35s}
[data-screen="menu"] .hud,[data-screen="how"] .hud{opacity:0;transform:translateY(-10px)}
.fighter-panel{display:flex;align-items:center;gap:13px}
.portrait{position:relative;width:66px;height:66px;border:1px solid rgba(84,220,255,.48);background:linear-gradient(145deg,rgba(21,68,102,.8),rgba(4,13,26,.94));clip-path:polygon(0 0,82% 0,100% 18%,100% 100%,18% 100%,0 82%);display:grid;place-items:center;color:var(--cyan);box-shadow:inset 0 0 24px rgba(38,204,255,.15)}
.portrait svg{width:43px;height:43px;filter:drop-shadow(0 0 6px rgba(51,235,255,.75))}
.portrait i{position:absolute;width:6px;height:6px;right:7px;top:7px;border-radius:50%;background:var(--green);box-shadow:0 0 10px var(--green)}
.vitals{width:min(31vw,370px);min-width:220px}
.vital-head{display:flex;justify-content:space-between;align-items:flex-end;line-height:1;margin:0 1px 5px}
.callsign{font-size:12px;font-weight:700;letter-spacing:.18em;color:#d9f9ff;text-shadow:0 1px 8px #000}
.callsign b{color:var(--cyan);font-weight:600}
.vital-number{font-family:var(--display);font-size:19px;letter-spacing:.08em;color:var(--white);text-shadow:0 0 9px rgba(53,233,255,.45)}
.energy-head{margin-top:7px}
