.bar{position:relative;height:15px;overflow:hidden;background:rgba(1,7,15,.86);border:1px solid rgba(131,214,255,.3);clip-path:polygon(0 0,100% 0,calc(100% - 8px) 100%,0 100%)}
.bar:before{content:"";position:absolute;inset:3px;background:repeating-linear-gradient(90deg,rgba(255,255,255,.1) 0 1px,transparent 1px 12.5%);z-index:3;opacity:.45}
.bar i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#1882ff,#34eaff 62%,#c5fbff);box-shadow:0 0 16px rgba(40,224,255,.75);transform-origin:left;transition:transform .25s cubic-bezier(.2,.75,.2,1),filter .2s}
