.bar .bar-glint{position:absolute;inset:0;background:linear-gradient(110deg,transparent 20%,rgba(255,255,255,.32) 50%,transparent 80%);transform:translateX(-100%);animation:barShine 4s 1.5s infinite;z-index:2}
@keyframes barShine{0%,65%{transform:translateX(-120%)}85%,100%{transform:translateX(120%)}}
.bar.low i{background:linear-gradient(90deg,#ff203f,#ff6074);box-shadow:0 0 16px rgba(255,56,83,.7);animation:lowPulse .6s ease-in-out infinite alternate}
