.battery b.flick{animation:batteryFlick .9s linear infinite}
@keyframes batteryFlick{50%{opacity:.45}}
.round-panel{display:flex;align-items:center;gap:17px;padding:9px 15px 10px 18px;border-top:1px solid rgba(116,220,255,.25);border-bottom:1px solid rgba(116,220,255,.14);background:linear-gradient(90deg,rgba(4,11,24,.2),rgba(4,11,24,.75));clip-path:polygon(14px 0,100% 0,100% 100%,0 100%,0 14px)}
