.round-block strong{font-family:var(--display);font-size:31px;font-weight:400;letter-spacing:.04em;line-height:.9;color:var(--white);text-shadow:0 0 16px rgba(51,225,255,.38)}
.round-block.kills strong{color:var(--cyan)}
.round-slash{width:1px;height:25px;background:linear-gradient(transparent,var(--line),transparent)}
.combo-readout{position:absolute;z-index:7;left:var(--safe-left);top:112px;display:flex;align-items:center;gap:9px;opacity:0;transform:translateX(-16px) skewX(-5deg);transition:opacity .18s,transform .18s;pointer-events:none;text-shadow:0 0 16px rgba(45,230,255,.55)}
.combo-readout.show{opacity:1;transform:translateX(0) skewX(-5deg)}
.combo-readout>span{font-family:var(--display);font-size:54px;line-height:.75;color:var(--cyan);-webkit-text-stroke:1px rgba(210,252,255,.7)}
.combo-readout div{display:flex;flex-direction:column;line-height:1;padding-top:4px}
