.combo-readout small{font-size:9px;letter-spacing:.13em;color:#7e9aae;margin-top:4px}
.wave-banner{position:absolute;z-index:9;left:50%;top:19%;transform:translate(-50%,-10px);display:flex;flex-direction:column;align-items:center;text-align:center;opacity:0;pointer-events:none;transition:opacity .35s,transform .35s}
