.wave-banner:before,.wave-banner:after{content:"";position:absolute;top:26px;width:140px;height:1px;background:linear-gradient(90deg,transparent,var(--cyan));box-shadow:0 0 8px var(--cyan)}
.wave-banner:before{right:112%}
.wave-banner:after{left:112%;transform:scaleX(-1)}
.wave-banner span{font-size:10px;letter-spacing:.38em;color:var(--cyan);margin-bottom:5px}
.wave-banner strong{font-family:var(--display);font-size:45px;font-weight:400;letter-spacing:.09em;line-height:1;text-shadow:0 0 25px rgba(51,223,255,.48)}
