.context-hint{position:absolute;z-index:7;left:50%;bottom:22px;transform:translateX(-50%);padding:7px 12px;border:1px solid rgba(83,210,255,.18);background:rgba(2,9,20,.78);color:#7797ad;font-size:10px;letter-spacing:.1em;white-space:nowrap;opacity:0;transition:opacity .3s;pointer-events:none}
.context-hint.show{opacity:1}
.context-hint kbd{display:inline-block;padding:1px 5px;margin:0 1px;border:1px solid rgba(77,215,255,.35);background:rgba(33,129,183,.16);color:#c9f8ff;font-family:var(--ui);font-size:9px}
