[data-screen="playing"] .context-hint{animation:hintFade 8s forwards}
@keyframes hintFade{0%,75%{opacity:1}100%{opacity:0}}

/* ---------- TOUCH CONTROLS ---------- */
.touch-ui{position:absolute;z-index:10;inset:auto var(--safe-right) var(--safe-bottom) var(--safe-left);display:flex;justify-content:space-between;align-items:flex-end;pointer-events:none;opacity:0;transform:translateY(18px);transition:opacity .35s,transform .35s}
