.how-card h2 em{font-style:normal;color:var(--cyan);text-shadow:0 0 25px rgba(47,219,255,.3)}
.how-grid{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:rgba(112,193,224,.13);border:1px solid rgba(112,193,224,.13)}
.how-grid article{background:#07111f;padding:19px 20px 21px}
.how-grid article>span{font-family:var(--display);font-size:15px;color:#3b6378;letter-spacing:.08em}
.how-grid h3{margin:5px 0 7px;font-size:12px;letter-spacing:.18em;color:#d3f3fa}
.how-grid p{margin:0;font-size:11.5px;line-height:1.4;color:#7b95a7;font-weight:500}
.how-controls{display:flex;flex-wrap:wrap;gap:7px 13px;align-items:center;margin-top:20px;padding-top:17px;border-top:1px solid rgba(112,193,224,.13);font-size:9px;letter-spacing:.1em;color:#6a899c}
.how-controls b{color:var(--cyan);margin-right:3px}
.pause-screen{background:rgba(2,6,13,.83);backdrop-filter:blur(12px)}
.pause-card{width:min(410px,88vw);padding:33px}
.pause-card h2{font-size:76px;margin-bottom:18px}
.pause-actions{display:flex;flex-direction:column;gap:8px}
.pause-card>p{margin:17px 0 0;font-size:10px;letter-spacing:.1em;color:#547084;text-align:center}

/* Game over */
.gameover-screen{background:linear-gradient(90deg,rgba(2,5,11,.95),rgba(2,5,11,.5) 55%,rgba(2,5,11,.8)),repeating-linear-gradient(90deg,transparent 0 90px,rgba(255,48,84,.025) 90px 91px);backdrop-filter:blur(6px);align-items:flex-start;justify-content:center;padding:max(22px,5vh) max(22px,7vw)}
.gameover-screen:before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 130%,rgba(101,12,31,.24),transparent 65%);pointer-events:none}
.gameover-card{position:relative;z-index:2;width:min(710px,92vw);margin:auto;border-left:1px solid rgba(255,77,101,.35);padding:7px 0 7px 29px}
.gameover-card:before{content:"";position:absolute;left:-1px;top:0;width:2px;height:100px;background:var(--red);box-shadow:0 0 17px rgba(255,52,79,.7)}
.gameover-card .eyebrow{color:#cf8591}
.gameover-card .eyebrow i{background:var(--red);box-shadow:0 0 8px var(--red)}
.gameover-card h2{margin:18px 0 15px;font-family:var(--display);font-size:clamp(80px,10vw,130px);font-weight:400;line-height:.72;letter-spacing:.01em;color:#f2f8fa;text-shadow:0 0 50px rgba(255,42,78,.13)}
.gameover-card h2 em{font-style:normal;color:transparent;-webkit-text-stroke:1px rgba(255,90,111,.82);text-shadow:0 0 30px rgba(255,43,76,.16)}
