  await page.goto('http://localhost:3000',{waitUntil:'networkidle'});
  await page.waitForTimeout(250);
  const menu = await page.evaluate(()=>({sw:document.documentElement.scrollWidth,cw:document.documentElement.clientWidth,sh:document.documentElement.scrollHeight,ch:document.documentElement.clientHeight,
    menuBox:(()=>{const r=document.querySelector('.menu-content').getBoundingClientRect();return {l:r.left,r:r.right,t:r.top,b:r.bottom}})(),
    actions:(()=>{const r=document.querySelector('.menu-actions').getBoundingClientRect();return {l:r.left,r:r.right,t:r.top,b:r.bottom}})()}));
  await page.screenshot({path:`screenshots/final-menu-${name}.png`});
  await page.getByRole('button',{name:'Start'}).click();
  await page.waitForTimeout(650);
  const play = await page.evaluate(()=>{
    const ids=['.dpad','.action-cluster','#pauseBtn','#muteBtn','.hud','.round-panel']; const out={};
    for(const s of ids){const el=document.querySelector(s);if(!el)continue;const r=el.getBoundingClientRect();out[s]={l:Math.round(r.left),r:Math.round(r.right),t:Math.round(r.top),b:Math.round(r.bottom),visible:getComputedStyle(el).opacity!=='0'&&r.width>0};}
    return {sw:document.documentElement.scrollWidth,cw:document.documentElement.clientWidth,sh:document.documentElement.scrollHeight,ch:document.documentElement.clientHeight,boxes:out};
  });
  console.log(name, 'menu', menu, '\n play', play, 'errors', errs);
  await page.screenshot({path:`screenshots/final-game-${name}.png`});
  await page.close();
}
await browser.close();
EOF
