import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args:['--no-sandbox'] });
const ctx = await browser.newContext({ viewport:{width:390,height:844}, hasTouch:true, isMobile:true, deviceScaleFactor:2 });
const page = await ctx.newPage();
const errs=[]; page.on('pageerror',e=>errs.push(e.message));
await page.goto('http://localhost:3000',{waitUntil:'networkidle'});
await page.tap('#startBtn');
await page.waitForTimeout(400);
await page.evaluate(()=>{const g=NeonStick;g.state.enemies.length=0;g.state.spawnQueue=[];g.state.waveActive=false;g.player.introGrace=0;g.player.invuln=999;g.player.x=innerWidth*.45;g.player.y=g.player.y;g.player.action='idle';g.player.actionTime=0;});
const startX = await page.evaluate(()=>NeonStick.player.x);
const right = page.locator('.pad.right');
await right.dispatchEvent('pointerdown',{pointerId:7,pointerType:'touch',isPrimary:true,bubbles:true});
await page.waitForTimeout(500);
const movedX = await page.evaluate(()=>NeonStick.player.x);
await right.dispatchEvent('pointerup',{pointerId:7,pointerType:'touch',isPrimary:true,bubbles:true});
const jump = page.locator('.pad.up');
await jump.dispatchEvent('pointerdown',{pointerId:8,pointerType:'touch',isPrimary:true,bubbles:true});
await page.waitForTimeout(100);
const jumpState = await page.evaluate(()=>({action:NeonStick.player.action,grounded:NeonStick.player.grounded,y:NeonStick.player.y}));
await jump.dispatchEvent('pointerup',{pointerId:8,pointerType:'touch',isPrimary:true,bubbles:true});
await page.waitForTimeout(900);
const quickSetup = await page.evaluate(()=>{const g=NeonStick,p=g.player;g.state.enemies.length=0;p.x=innerWidth*.5;p.y=p.y;p.action='idle';p.actionTime=0;p.grounded=true;p.vy=0;p.facing=1;const e=g.spawnEnemy('red',p.x+60,'flank');e.state='chase';e.cooldown=999;e.speed=0;e.hp=200;e.maxHp=200;return e.hp;});
const quick = page.locator('.action-quick');
await quick.dispatchEvent('pointerdown',{pointerId:9,pointerType:'touch',isPrimary:true,bubbles:true});
await page.waitForTimeout(60);
const quickMid = await page.evaluate(()=>({action:NeonStick.player.action,enemyHp:NeonStick.enemies[0]?.hp}));
await quick.dispatchEvent('pointerup',{pointerId:9,pointerType:'touch',isPrimary:true,bubbles:true});
await page.waitForTimeout(300);
const quickAfter = await page.evaluate(()=>({action:NeonStick.player.action,enemyHp:NeonStick.enemies[0]?.hp,energy:NeonStick.player.energy}));
const sp = await page.evaluate(()=>{NeonStick.player.energy=100;return true;});
const special = page.locator('.action-special');
await special.dispatchEvent('pointerdown',{pointerId:10,pointerType:'touch',isPrimary:true,bubbles:true});
await page.waitForTimeout(260);
const specialMid = await page.evaluate(()=>({action:NeonStick.player.action,energy:NeonStick.player.energy,bullet:NeonStick.state.bulletTime,slow:NeonStick.state.slow}));
await special.dispatchEvent('pointerup',{pointerId:10,pointerType:'touch',isPrimary:true,bubbles:true});
await page.waitForTimeout(1300);
await page.tap('#pauseBtn');
await page.waitForTimeout(120);
const pause = await page.evaluate(()=>({screen:document.querySelector('#app').dataset.screen,paused:NeonStick.state.paused,pauseVisible:!document.querySelector('#pausePanel').hidden}));
await page.tap('#resumeBtn');
await page.waitForTimeout(120);
const resume = await page.evaluate(()=>({screen:document.querySelector('#app').dataset.screen,paused:NeonStick.state.paused}));
console.log({startX,movedX,jumpState,quickSetup,quickMid,quickAfter,specialMid,pause,resume,errs});
await page.screenshot({path:'screenshots/final-touch-game.png'});
