cat > /tmp/adnatural.mjs <<'EOF'
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const b=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
const p=await b.newPage({viewport:{width:1440,height:900}}); const e=[]; p.on('pageerror',x=>e.push(x.message));
await p.goto('http://localhost:3000',{waitUntil:'networkidle'}); await p.getByRole('button',{name:'Start'}).click(); await p.waitForTimeout(200);
for(let i=0;i<2;i++){await p.evaluate(()=>NeonStick.diePlayer()); await p.waitForTimeout(1400); if(i===0){await p.click('#restartBtn'); await p.waitForTimeout(250);}}
await p.click('#watchAdBtn'); const t=Date.now(); await p.waitForTimeout(4250);
console.log(await p.evaluate(()=>({screen:document.querySelector('#app').dataset.screen,hp:NeonStick.player.hp,deaths:NeonStick.state.deaths,adTime:NeonStick.state.adTime,adDone:NeonStick.state.adDone})),'elapsed',Date.now()-t,'errs',e);
await b.close();
EOF
node /tmp/adnatural.mjs 2>&1

cat > /tmp/wallground.mjs <<'EOF'
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const b=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
const p=await b.newPage({viewport:{width:1440,height:900}}); const e=[]; p.on('pageerror',x=>e.push(x.message));
await p.goto('http://localhost:3000',{waitUntil:'networkidle'}); await p.getByRole('button',{name:'Start'}).click(); await p.waitForTimeout(250);
await p.evaluate(()=>{const g=NeonStick;g.state.enemies.length=0;g.state.spawnQueue=[];g.state.waveActive=false;g.player.introGrace=0;g.player.invuln=999;g.player.x=innerWidth-60;g.player.action='idle';g.player.actionTime=0;});
await p.keyboard.down('d'); await p.waitForTimeout(500);
console.log('cling',await p.evaluate(()=>({a:NeonStick.player.action,side:NeonStick.player.wallSide,x:NeonStick.player.x,grounded:NeonStick.player.grounded})));
await p.keyboard.press('w'); await p.waitForTimeout(160);
console.log('kick',await p.evaluate(()=>({a:NeonStick.player.action,vx:NeonStick.player.vx,vy:NeonStick.player.vy,x:NeonStick.player.x,grounded:NeonStick.player.grounded})));
await p.keyboard.up('d'); await b.close();
EOF
node /tmp/wallground.mjs 2>&1

